4d3689f644a65592.text:
{
  "name": "Waiting list: discouraged referrals and working harder",
  "timeUnit": "month",
  "T": 60,
  "dt": 0.125,
  "stocks": [
    {
      "id": "wl",
      "name": "Waiting list",
      "init": "32000",
      "units": "patients",
      "nonNegative": true
    }
  ],
  "flows": [
    {
      "id": "ref",
      "name": "Referrals",
      "eq": "Need_in_the_population * (Perceived_wait / Reference_wait) ^ (-Referral_sensitivity)",
      "units": "patients/month",
      "to": "wl"
    },
    {
      "id": "trt",
      "name": "Treatments",
      "eq": "MIN(Capacity, Waiting_list / Minimum_treatment_time)",
      "units": "patients/month",
      "from": "wl"
    }
  ],
  "vars": [
    {
      "id": "need",
      "name": "Need in the population",
      "eq": "4000 + STEP(Need_increase, 12)",
      "units": "patients/month"
    },
    {
      "id": "ni",
      "name": "Need increase",
      "eq": "400",
      "units": "patients/month"
    },
    {
      "id": "wt",
      "name": "Waiting time",
      "eq": "Waiting_list / Treatments",
      "units": "months"
    },
    {
      "id": "pw",
      "name": "Perceived wait",
      "eq": "SMOOTH(Waiting_time, Perception_time)",
      "units": "months"
    },
    {
      "id": "pt",
      "name": "Perception time",
      "eq": "6",
      "units": "months"
    },
    {
      "id": "rw",
      "name": "Reference wait",
      "eq": "8",
      "units": "months"
    },
    {
      "id": "rs",
      "name": "Referral sensitivity",
      "eq": "0.3",
      "units": "dimensionless"
    },
    {
      "id": "nc",
      "name": "Normal capacity",
      "eq": "4000",
      "units": "patients/month"
    },
    {
      "id": "pr",
      "name": "Pressure",
      "eq": "Waiting_time / Reference_wait",
      "units": "dimensionless"
    },
    {
      "id": "ot",
      "name": "Overtime",
      "eq": "MIN(Maximum_overtime, 0.5 * MAX(0, Pressure - 1))",
      "units": "extra clinics/month"
    },
    {
      "id": "mo",
      "name": "Maximum overtime",
      "eq": "0.2",
      "units": "fraction"
    },
    {
      "id": "cap",
      "name": "Capacity",
      "eq": "Normal_capacity + Overtime",
      "units": "patients/month"
    },
    {
      "id": "mtt",
      "name": "Minimum treatment time",
      "eq": "0.5",
      "units": "month"
    }
  ]
}

