eebc54a5bb6fa02b.text:
{
  "criticisms": [
    {
      "element": "Referrals",
      "quote": "Perceived_wait / Reference_wait",
      "kind": "information",
      "why": "GPs act on the wait they believe, and the rule reads the perceived wait, not the true Waiting_time. It also reads Need_in_the_population, but as the source of the patients who present, not as information a GP uses.",
      "suggestion": "No change: this rule already uses what GPs can know."
    },
    {
      "element": "Pressure",
      "quote": "Waiting_list / Target_list",
      "kind": "information",
      "why": "Managers see the list in a monthly report, so they act on a count up to a month old. Reading the stock itself makes their response faster than it can be in practice.",
      "suggestion": "Read a Reported list: a first-order smooth of the list over a reporting delay of about one month."
    },
    {
      "element": "Overtime",
      "quote": "0.5 * MAX(0, Pressure - 1)",
      "kind": "constant",
      "why": "The 0.5 is an unnamed response: half a unit of extra capacity per unit of pressure above normal. No interview gives it, and written into the equation it cannot be varied or tested.",
      "suggestion": "Name it (Overtime response), say it is assumed, and test how much the results depend on it."
    },
    {
      "element": "Maximum overtime",
      "quote": "0.2",
      "kind": "constant",
      "why": "The cap of 20% extra capacity has no source. The consultant says extra clinics can only be kept up 'for so long', which is about how long, not how much.",
      "suggestion": "Record it as an assumption or ask the consultant. What limits overtime over time is fatigue, the Overtime -> Fatigue link of the full hypothesis."
    },
    {
      "element": "Need in the population",
      "quote": "4000 + STEP(Need_increase, 12)",
      "kind": "constant",
      "why": "The base need of 4000 and the month of the rise, 12, are written into the equation. 4000 is also Normal capacity: change one and the other will not follow.",
      "suggestion": "Name them, for example Base need and Month of rise."
    },
    {
      "element": "Target list",
      "quote": "32000",
      "kind": "constant",
      "why": "The target was set equal to the starting list so the model starts in balance. That is a modelling convenience, not the board's target, yet the overtime rule treats any list above it as pressure.",
      "suggestion": "State the source. If the board has a real target, use it and say how the model is started."
    },
    {
      "element": "Waiting time",
      "quote": "MAX(1, Treatments)",
      "kind": "other",
      "why": "The guard stops a division by zero, but with no treatments the wait it reports is the list divided by one patient a month, which has no meaning. Only the GPs' perception reads it, so the harm is contained.",
      "suggestion": "Keep the guard, document it, and never report Waiting time from a run with no treatments."
    }
  ],
  "molecules": [
    {
      "key": "smooth",
      "where": "Pressure",
      "why": "A first-order smooth of the list over the reporting delay is the Reported list that managers see."
    },
    {
      "key": "overtime",
      "where": "Overtime",
      "why": "Indicated overtime as desired over actual capacity, capped by a limit, removes the free 0.5 response. It needs a desired treatment rate, which this model lacks."
    },
    {
      "key": "effectFatigue",
      "where": "Capacity",
      "why": "Sustained overtime builds fatigue that lowers productivity, the R2 loop of the full hypothesis. It would make the limit on overtime part of the model."
    }
  ]
}
